<script setup lang="ts">
import {computed,onBeforeUnmount,onMounted,reactive,ref} from 'vue';
import {createSnapshotUnlockSession} from '../../../../../preview-data/snapshot-unlock.mjs';
import {unlockSnapshot} from '../data/stored-snapshots';
const props=defineProps<{records:any[]}>();const emit=defineEmits(['continue']);
const session=reactive(createSnapshotUnlockSession(props.records,unlockSnapshot));
const busy=ref(false),tested=ref(false),error=ref('');
const protectedRows=computed(()=>session.rows.filter((row:any)=>row.encrypted));
async function test(row?:any){busy.value=true;error.value='';try{if(row)await session.verify(row);else{await session.verifyAll();tested.value=true;}}finally{busy.value=false;}}
function edit(row:any,event:Event){tested.value=false;session.setPassword(row,(event.target as HTMLInputElement).value);}
function apply(row:any){tested.value=false;session.applyToAll(row);}
async function proceed(){await test();if(session.eligible.length<2){error.value='At least two successfully verified snapshots are needed. Correct the passwords or select more snapshots.';return;}const result=session.result();session.clear();emit('continue',result);}
onMounted(async()=>{for(const row of session.rows.filter((item:any)=>!item.encrypted))await session.verify(row);});
onBeforeUnmount(()=>session.clear());
</script>
<template><section class="unlock-step" aria-label="Verify Snapshot Passwords"><h2>Verify Snapshot Passwords</h2><p>Unencrypted snapshots are included. Protected snapshots are processed only after their password is verified. Passwords are kept only for this merge session.</p><div v-for="row in protectedRows" :key="row.id" class="unlock-row"><strong>{{row.scope?.label||row.name}}<small>{{row.id}}</small></strong><label>Password<input type="password" autocomplete="off" :disabled="busy" :value="row.password" :aria-label="`Password for ${row.name}`" @input="edit(row,$event)"></label><button type="button" :disabled="busy||!row.password" @click="apply(row)">Apply To All Snapshots</button><button type="button" :disabled="busy||!row.password" @click="test(row)">Test Password</button><span role="status">{{row.status}}</span></div><p v-if="!protectedRows.length">No selected snapshots require a password.</p><div v-if="session.excluded.length" role="alert" class="skip-warning"><strong>These Snapshots Will Not Be Processed</strong><ul><li v-for="row in session.excluded" :key="row.id">{{row.scope?.label||row.name}} ({{row.id}}): {{row.status}}</li></ul></div><p role="status">{{session.eligible.length}} / {{session.rows.length}} Snapshots Verified</p><p v-if="error" role="alert">{{error}}</p><button type="button" :disabled="busy" @click="test()">{{busy?'Verifying…':'Test All Passwords'}}</button><button type="button" :disabled="busy||!tested||session.eligible.length<2" @click="proceed">Continue With Verified Snapshots</button></section></template>
<style scoped>.unlock-step{padding:24px;background:var(--box-bg);border:1px solid var(--border);border-radius:6px;overflow:auto}.unlock-row{display:flex;align-items:end;gap:12px;flex-wrap:wrap;padding:16px 0;border-bottom:1px solid var(--border)}.unlock-row strong{min-width:180px}.unlock-row small{display:block;font-size:11px;color:var(--muted)}.unlock-row label{display:flex;flex-direction:column;gap:8px}.unlock-row input{padding:10px;background:var(--input-bg);color:inherit;border:1px solid var(--border)}button{padding:10px;background:#326fb4;color:white;border:0;border-radius:4px;margin:4px;cursor:pointer}button:disabled{opacity:.5}.skip-warning{background:#4c282e;color:#ffb3ad;padding:16px;margin-top:20px}p{line-height:1.5}</style>
